[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
:root {
  --bg: #0A0A0A;
  --bg-elevated: #141414;
  --bg-card: #1A1A1A;
  --text: #FFFFFF;
  --text-secondary: #A0A0A0;
  --text-muted: #666666;
  --accent: #3B82F6;
  --accent-glow: rgba(59, 130, 246, 0.3);
  --border: #2A2A2A;
  --border-light: #3A3A3A;
  --radius: 12px;
  --radius-lg: 20px;
  --max-width: 1280px;
  --nav-height: 80px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 10000;
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
  padding: 20px 0;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.cookie-text { font-size: 14px; color: var(--text-secondary); line-height: 1.5; }
.cookie-text a { color: var(--accent); text-decoration: none; }
.cookie-text a:hover { text-decoration: underline; }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 10px 24px; border-radius: 8px; font-size: 14px; font-weight: 600;
  cursor: pointer; border: none; transition: all 0.2s ease;
  font-family: inherit; text-decoration: none; white-space: nowrap;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: #2563EB; transform: translateY(-1px); }
.btn-secondary { background: transparent; color: var(--text); border: 1px solid var(--border-light); }
.btn-secondary:hover { border-color: var(--text-secondary); }
.btn-ghost { background: transparent; color: var(--text-secondary); padding: 10px 16px; }
.btn-ghost:hover { color: var(--text); }

/* ===== NAVIGATION ===== */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  height: var(--nav-height); background: rgba(10,10,10,0.85);
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: background 0.3s ease;
}
.nav.scrolled { background: rgba(10,10,10,0.95); }
.nav-inner {
  max-width: var(--max-width); margin: 0 auto;
  padding: 0 40px; height: 100%;
  display: flex; align-items: center; justify-content: space-between;
}
.nav-logo {
  font-size: 24px; font-weight: 800; letter-spacing: -0.5px;
  color: var(--text); text-decoration: none;
}
.nav-logo span { color: var(--accent); }
.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a {
  color: var(--text-secondary); text-decoration: none;
  font-size: 14px; font-weight: 500; transition: color 0.2s ease; position: relative;
}
.nav-links a:hover, .nav-links a.active { color: var(--text); }
.nav-links a::after {
  content: ''; position: absolute; bottom: -4px; left: 0; width: 0; height: 1px;
  background: var(--accent); transition: width 0.2s ease;
}
.nav-links a:hover::after { width: 100%; }

/* Language Selector */
.lang-selector { position: relative; }
.lang-btn {
  display: flex; align-items: center; gap: 6px;
  background: none; border: 1px solid var(--border-light); border-radius: 6px;
  color: var(--text-secondary); font-size: 13px; font-weight: 500;
  padding: 6px 12px; cursor: pointer; font-family: inherit;
  transition: all 0.2s ease;
}
.lang-btn:hover { border-color: var(--text-secondary); color: var(--text); }
.lang-btn .arrow { font-size: 10px; transition: transform 0.2s ease; }
.lang-selector.open .lang-btn .arrow { transform: rotate(180deg); }
.lang-dropdown {
  position: absolute; top: calc(100% + 8px); right: 0;
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: 8px; padding: 6px; min-width: 160px;
  opacity: 0; visibility: hidden; transform: translateY(-8px);
  transition: all 0.2s ease; list-style: none;
}
.lang-selector.open .lang-dropdown { opacity: 1; visibility: visible; transform: translateY(0); }
.lang-dropdown li a {
  display: block; padding: 8px 12px; border-radius: 6px;
  color: var(--text-secondary); text-decoration: none; font-size: 13px;
  transition: all 0.15s ease;
}
.lang-dropdown li a:hover, .lang-dropdown li a.active { background: rgba(255,255,255,0.06); color: var(--text); }

.nav-toggle { display: none; flex-direction: column; gap: 5px; cursor: pointer;
  background: none; border: none; padding: 4px; z-index: 1001; }
.nav-toggle span {
  display: block; width: 24px; height: 2px; background: var(--text);
  transition: all 0.3s ease;
}

/* ===== HERO CAROUSEL ===== */
.hero {
  position: relative; min-height: 100vh; display: flex; align-items: center;
  overflow: hidden; padding-top: var(--nav-height);
}
.hero-slides { position: relative; width: 100%; }
.hero-slide {
  position: absolute; top: 0; left: 0; width: 100%;
  opacity: 0; transform: translateY(20px);
  transition: all 0.7s cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: none; padding: 80px 40px;
}
.hero-slide.active { position: relative; opacity: 1; transform: translateY(0); pointer-events: auto; }
.hero-content {
  max-width: var(--max-width); margin: 0 auto;
  display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center;
}
.hero-visual {
  aspect-ratio: 4/3; background: var(--bg-card); border-radius: var(--radius-lg);
  position: relative; overflow: hidden; border: 1px solid var(--border);
}
.hero-visual::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, var(--accent-glow) 0%, transparent 70%);
  opacity: 0.5;
}
.hero-visual-icon {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  font-size: 72px; opacity: 0.4;
}
.hero-text .label {
  display: inline-block; font-size: 12px; font-weight: 700;
  letter-spacing: 2px; color: var(--accent); margin-bottom: 24px;
  text-transform: uppercase;
}
.hero-text h1 { font-size: 52px; font-weight: 800; line-height: 1.08; letter-spacing: -1.5px; margin-bottom: 24px; }
.hero-text p { font-size: 18px; color: var(--text-secondary); margin-bottom: 32px; max-width: 480px; line-height: 1.6; }
.hero-text .btn { font-size: 15px; padding: 14px 32px; border-radius: 8px; }

.hero-controls {
  position: absolute; bottom: 48px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 24px; z-index: 10;
}
.hero-arrow {
  width: 44px; height: 44px; border-radius: 50%;
  background: rgba(255,255,255,0.06); border: 1px solid var(--border);
  color: var(--text); cursor: pointer; display: flex; align-items: center;
  justify-content: center; font-size: 18px; transition: all 0.2s ease;
}
.hero-arrow:hover { background: rgba(255,255,255,0.12); border-color: var(--border-light); }
.hero-dots { display: flex; gap: 10px; }
.hero-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--border-light);
  border: none; cursor: pointer; transition: all 0.3s ease;
}
.hero-dot.active { background: var(--accent); width: 28px; border-radius: 4px; }

/* ===== SECTION COMMONS ===== */
.section { padding: 120px 40px; }
.section-header { text-align: center; margin-bottom: 80px; }
.section-label {
  font-size: 12px; font-weight: 700; letter-spacing: 2px;
  color: var(--accent); text-transform: uppercase; margin-bottom: 16px; display: block;
}
.section-header h2 { font-size: 48px; font-weight: 800; letter-spacing: -1px; line-height: 1.1; margin-bottom: 16px; }
.section-header p { font-size: 18px; color: var(--text-secondary); max-width: 640px; margin: 0 auto; }

/* ===== TEAM SECTION ===== */
.team-section { background: var(--bg-elevated); }
.region-tabs {
  display: flex; justify-content: center; gap: 8px; margin-bottom: 56px; flex-wrap: wrap;
}
.region-tab {
  padding: 12px 28px; border-radius: 100px; font-size: 15px; font-weight: 600;
  background: transparent; border: 1px solid var(--border); color: var(--text-secondary);
  cursor: pointer; transition: all 0.25s ease; font-family: inherit;
}
.region-tab:hover { border-color: var(--text-secondary); color: var(--text); }
.region-tab.active { background: var(--accent); border-color: var(--accent); color: #fff; }

.team-carousel-wrapper { position: relative; max-width: var(--max-width); margin: 0 auto; }
.team-carousel {
  display: flex; gap: 24px; overflow-x: auto; scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch; scrollbar-width: none; padding-bottom: 8px;
}
.team-carousel::-webkit-scrollbar { display: none; }

.team-card {
  flex: 0 0 calc(50% - 12px); min-width: 340px; scroll-snap-align: start;
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 40px; transition: border-color 0.3s ease;
}
.team-card:hover { border-color: var(--border-light); }
.team-card-photo {
  width: 72px; height: 72px; border-radius: 50%; margin-bottom: 24px;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; font-weight: 700; color: #fff;
}
.team-card blockquote {
  font-size: 17px; line-height: 1.6; color: var(--text); font-style: italic;
  margin-bottom: 24px; min-height: 90px;
}
.team-card blockquote::before { content: '\201C'; }
.team-card blockquote::after { content: '\201D'; }
.team-card .name { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.team-card .title-loc { font-size: 14px; color: var(--text-secondary); margin-bottom: 20px; }
.team-card .btn { font-size: 13px; padding: 8px 20px; }

.team-nav {
  display: flex; justify-content: center; align-items: center; gap: 16px; margin-top: 40px;
}
.team-nav-btn {
  width: 40px; height: 40px; border-radius: 50%;
  background: transparent; border: 1px solid var(--border); color: var(--text);
  cursor: pointer; font-size: 16px; transition: all 0.2s ease;
  display: flex; align-items: center; justify-content: center;
}
.team-nav-btn:hover { border-color: var(--text-secondary); background: rgba(255,255,255,0.04); }
.team-nav-btn:disabled { opacity: 0.3; cursor: default; }

/* ===== WORK SHOWCASE ===== */
.work-carousel-wrapper { position: relative; max-width: 100%; overflow: hidden; }
.work-carousel {
  display: flex; gap: 24px; overflow-x: auto; scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch; scrollbar-width: none;
  padding: 0 40px 8px;
}
.work-carousel::-webkit-scrollbar { display: none; }
.work-card {
  flex: 0 0 440px; scroll-snap-align: start;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden; transition: border-color 0.3s ease;
  cursor: pointer;
}
.work-card:hover { border-color: var(--border-light); }
.work-card-thumb {
  height: 280px; background: var(--bg-elevated); position: relative; overflow: hidden;
}
.work-card-thumb::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 50%, var(--accent-glow) 0%, transparent 60%);
  opacity: 0.3;
}
.work-card-thumb-inner {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-size: 48px; opacity: 0.25;
}
.work-card-body { padding: 28px 32px; }
.work-card-body h3 { font-size: 20px; font-weight: 700; margin-bottom: 8px; letter-spacing: -0.3px; }
.work-card-body .client { font-size: 14px; color: var(--accent); font-weight: 600; margin-bottom: 12px; }
.work-card-body p { font-size: 14px; color: var(--text-secondary); line-height: 1.5; }

.work-controls {
  display: flex; justify-content: center; align-items: center; gap: 24px; margin-top: 48px;
}
.work-arrow {
  width: 44px; height: 44px; border-radius: 50%;
  background: transparent; border: 1px solid var(--border); color: var(--text);
  cursor: pointer; font-size: 18px; transition: all 0.2s ease;
  display: flex; align-items: center; justify-content: center;
}
.work-arrow:hover { border-color: var(--text-secondary); background: rgba(255,255,255,0.04); }

/* ===== CTA BANNER ===== */
.cta-banner {
  text-align: center; padding: 120px 40px;
  background: radial-gradient(ellipse at center, rgba(59,130,246,0.08) 0%, transparent 60%);
}
.cta-banner h2 { font-size: 56px; font-weight: 800; letter-spacing: -1.5px; line-height: 1.08; margin-bottom: 24px; }
.cta-banner p { font-size: 18px; color: var(--text-secondary); max-width: 640px; margin: 0 auto 40px; line-height: 1.6; }
.cta-banner .btn { font-size: 16px; padding: 16px 40px; border-radius: 8px; }

/* ===== HOW WE WORK ===== */
.hww-grid {
  max-width: var(--max-width); margin: 0 auto;
  display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center;
}
.hww-visual {
  aspect-ratio: 4/3; background: var(--bg-card); border-radius: var(--radius-lg);
  border: 1px solid var(--border); position: relative; overflow: hidden;
}
.hww-visual::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 40%, var(--accent-glow) 0%, transparent 60%);
  opacity: 0.4;
}
.hww-visual-icon {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  font-size: 80px; opacity: 0.3;
}
.hww-text h2 { font-size: 42px; font-weight: 800; letter-spacing: -1px; line-height: 1.1; margin-bottom: 20px; }
.hww-text p { font-size: 17px; color: var(--text-secondary); line-height: 1.7; margin-bottom: 32px; }

/* ===== INSIGHTS ===== */
.insights-section { background: var(--bg-elevated); }
.insights-grid {
  max-width: var(--max-width); margin: 0 auto;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px;
}
.insight-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 28px; transition: all 0.3s ease;
  cursor: pointer; position: relative; overflow: hidden;
}
.insight-card:hover { border-color: var(--border-light); transform: translateY(-4px); }
.insight-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: var(--accent); transform: scaleX(0); transform-origin: left;
  transition: transform 0.3s ease;
}
.insight-card:hover::before { transform: scaleX(1); }
.insight-type {
  font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase;
  color: var(--accent); margin-bottom: 12px;
}
.insight-card h4 { font-size: 17px; font-weight: 700; line-height: 1.3; margin-bottom: 16px; }
.insight-cta { font-size: 13px; font-weight: 600; color: var(--text-secondary); display: flex; align-items: center; gap: 6px; }
.insight-card:hover .insight-cta { color: var(--accent); }

/* ===== PRINCIPLES ===== */
.principles-grid {
  max-width: var(--max-width); margin: 0 auto;
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px;
}
.principle-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 48px; transition: border-color 0.3s ease;
}
.principle-card:hover { border-color: var(--border-light); }
.principle-num {
  font-size: 48px; font-weight: 900; color: rgba(59,130,246,0.15);
  line-height: 1; margin-bottom: 16px;
}
.principle-card h3 { font-size: 22px; font-weight: 700; margin-bottom: 12px; letter-spacing: -0.3px; }
.principle-card p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; }

/* ===== FOOTER ===== */
.footer { background: #050505; border-top: 1px solid var(--border); padding: 80px 40px 40px; }
.footer-inner { max-width: var(--max-width); margin: 0 auto; }
.footer-ctas { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; padding-bottom: 60px; border-bottom: 1px solid var(--border); margin-bottom: 60px; }
.footer-cta h3 { font-size: 22px; font-weight: 700; margin-bottom: 12px; }
.footer-cta p { font-size: 15px; color: var(--text-secondary); margin-bottom: 20px; line-height: 1.5; }
.footer-bottom { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 20px; }
.footer-links { display: flex; gap: 20px; flex-wrap: wrap; list-style: none; }
.footer-links a { color: var(--text-muted); text-decoration: none; font-size: 13px; transition: color 0.2s; }
.footer-links a:hover { color: var(--text-secondary); }
.footer-legal { color: var(--text-muted); font-size: 13px; }
.footer-legal a { color: var(--text-muted); text-decoration: none; }
.footer-legal a:hover { color: var(--text-secondary); }

/* ===== MOBILE NAV OVERLAY ===== */
.mobile-menu {
  position: fixed; inset: 0; z-index: 999; background: var(--bg);
  display: flex; align-items: center; justify-content: center;
  opacity: 0; visibility: hidden; transition: all 0.3s ease;
}
.mobile-menu.open { opacity: 1; visibility: visible; }
.mobile-menu ul { list-style: none; text-align: center; }
.mobile-menu li { margin-bottom: 24px; }
.mobile-menu a { color: var(--text); text-decoration: none; font-size: 28px; font-weight: 700; letter-spacing: -0.5px; transition: color 0.2s; }
.mobile-menu a:hover { color: var(--accent); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-content { grid-template-columns: 1fr; gap: 40px; }
  .hero-visual { aspect-ratio: 16/9; }
  .hero-text h1 { font-size: 40px; }
  .insights-grid { grid-template-columns: repeat(2, 1fr); }
  .hww-grid { grid-template-columns: 1fr; gap: 48px; }
  .hww-visual { aspect-ratio: 16/9; }
  .principles-grid { grid-template-columns: 1fr; }
  .team-card { flex: 0 0 70%; min-width: 300px; }
  .work-card { flex: 0 0 360px; }
  .cta-banner h2 { font-size: 40px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-toggle { display: flex; }
  .nav-inner { padding: 0 20px; }
  .section { padding: 80px 20px; }
  .hero { min-height: auto; }
  .hero-slide { padding: 60px 20px; }
  .hero-text h1 { font-size: 32px; }
  .hero-text p { font-size: 16px; }
  .hero-controls { bottom: 24px; }
  .section-header h2 { font-size: 32px; }
  .section-header p { font-size: 16px; }
  .team-card { flex: 0 0 85%; min-width: 260px; padding: 28px; }
  .team-card blockquote { font-size: 15px; min-height: auto; }
  .work-card { flex: 0 0 300px; }
  .work-carousel { padding: 0 20px 8px; }
  .cta-banner h2 { font-size: 32px; }
  .cta-banner { padding: 80px 20px; }
  .insights-grid { grid-template-columns: 1fr; }
  .principles-grid { grid-template-columns: 1fr; }
  .principle-card { padding: 32px; }
  .footer-ctas { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-links { justify-content: center; }
  .cookie-inner { padding: 0 20px; flex-direction: column; text-align: center; }
  .cookie-actions { width: 100%; justify-content: center; }
  .region-tab { padding: 10px 20px; font-size: 13px; }
  .hww-text h2 { font-size: 32px; }
}

@media (max-width: 480px) {
  .hero-text h1 { font-size: 28px; }
  .work-card { flex: 0 0 260px; }
  .team-card { flex: 0 0 90%; min-width: 240px; }
}
</style>
</head>
<body>

<!-- ===== COOKIE CONSENT BANNER ===== -->
<div class="cookie-banner" id="cookieBanner" role="dialog" aria-label="Cookie consent">
  <div class="cookie-inner">
    <p class="cookie-text">
      We use cookies to enhance your experience, analyze site traffic, and deliver personalized content.
      By clicking "Accept All", you consent to our use of cookies. See our
      <a href="#">Cookie Policy</a> and <a href="#">Privacy Policy</a>.
    </p>
    <div class="cookie-actions">
      <button class="btn btn-ghost" id="cookieSettings">Cookie Settings</button>
      <button class="btn btn-secondary" id="cookieDecline">Decline All</button>
      <button class="btn btn-primary" id="cookieAccept">Accept All</button>
    </div>
  </div>
</div>

<!-- ===== NAVIGATION ===== -->
<nav class="nav" id="nav">
  <div class="nav-inner">
    <a href="#" class="nav-logo">Leap<span>Studio</span></a>
    <ul class="nav-links" id="navLinks">
      <li><a href="#insights">Insights</a></li>
      <li><a href="#work">Work</a></li>
      <li><a href="#services">Services</a></li>
      <li><a href="#culture">Culture</a></li>
      <li><a href="#make-your-mark">Make Your Mark</a></li>
      <li><a href="#contact">Contact Us</a></li>
    </ul>
    <div class="lang-selector" id="langSelector">
      <button class="lang-btn" id="langBtn" aria-haspopup="true" aria-expanded="false">
        Global EN <span class="arrow">&#9662;</span>
      </button>
